#ifndef MARK_UNICODE_H
#define MARK_UNICODE_H
#include <stddef.h>

/* Go's unicode package properties, as goldmark v1.6.0 and Hugo 0.120.4 use
 * them, for any code point c (values past 0x10FFFF have none of them).
 * mark_unicode.c is generated by tools/gen_unicode. */
int mark_is_punct(unsigned long c);   /* unicode.IsPunct */
int mark_is_space(unsigned long c);   /* unicode.IsSpace */
int mark_is_letter(unsigned long c);  /* unicode.IsLetter */
int mark_is_digit(unsigned long c);   /* unicode.IsDigit */
unsigned long mark_to_lower(unsigned long c); /* unicode.ToLower */

#endif
